from launch import LaunchDescription
from launch_ros.actions import Node
from moveit_configs_utils import MoveItConfigsBuilder
from ament_index_python.packages import get_package_share_directory
import os
import yaml


def generate_launch_description():
    # Use the moveitconfig package generated by MoveIt Setup Assistant
    moveit_config = MoveItConfigsBuilder("panda", package_name="panda_moveit_config").to_moveit_configs()
    
    # ⭐ 显式加载 joint_limits.yaml
    joint_limits_yaml_path = os.path.join(
        get_package_share_directory('panda_moveit_config'),
        'config',
        'joint_limits.yaml'
    )
    
    with open(joint_limits_yaml_path, 'r') as file:
        joint_limits_yaml = yaml.safe_load(file)
    
    # 将 joint_limits 包装为 robot_description_planning 参数
    joint_limits_param = {'robot_description_planning': joint_limits_yaml}
    
    # Robot State Publisher
    robot_state_publisher = Node(
        package='robot_state_publisher',
        executable='robot_state_publisher',
        name='robot_state_publisher',
        output='screen',
        parameters=[moveit_config.robot_description],
    )
    
    # Static TF: world -> panda_link0
    static_tf = Node(
        package='tf2_ros',
        executable='static_transform_publisher',
        name='static_transform_publisher',
        arguments=['0', '0', '0', '0', '0', '0', 'world', 'panda_link0'],
        output='screen',
    )
    
    # Joint State Publisher GUI
    joint_state_publisher_gui = Node(
        package='joint_state_publisher_gui',
        executable='joint_state_publisher_gui',
        name='joint_state_publisher_gui',
    )

    # RViz with MoveIt config
    rviz_config_file = os.path.join(
        get_package_share_directory('panda_moveit_config'),
        'config',
        'moveit.rviz'
    )
    
    rviz = Node(
        package='rviz2',
        executable='rviz2',
        name='rviz2',
        output='log',
        arguments=['-d', rviz_config_file],
        parameters=[
            moveit_config.robot_description,
            moveit_config.robot_description_semantic,
            moveit_config.planning_pipelines,
            moveit_config.robot_description_kinematics,
        ],
    )

    # MoveGroup node
    move_group_node = Node(
        package='moveit_ros_move_group',
        executable='move_group',
        name='move_group',
        output='screen',
        parameters=[moveit_config.to_dict()],
    )

    # Z Plan node
    z_plan_node = Node(
        package='z_plan',
        executable='z_plan_node',
        name='z_plan_node',
        output='screen',
        parameters=[
            moveit_config.robot_description,
            moveit_config.robot_description_semantic,
            moveit_config.robot_description_kinematics,
            moveit_config.planning_pipelines,
            joint_limits_param,  # ⭐ 使用我们手动加载的 joint_limits
        ],
    )

    return LaunchDescription([
        robot_state_publisher,
        static_tf,
        joint_state_publisher_gui,
        move_group_node,
        rviz,
        z_plan_node,
    ])

